instrument tof_spectrometer {
    // Instrument parameters
    parameter double Lmin = 4.9;
    parameter double Lmax = 5.1;
    parameter double lambda0 = 5.0;
    parameter double Pulse_width = 2.857e-3;
    parameter int Num_pulses = 1;
    parameter double GUI_start = 2.0;
    parameter double FO1_DIST = 6.0;
    parameter double L_ballistic_begin = 19.5;
    parameter double L_ballistic_end = 17.0;
    parameter double Length = 100.0;
    parameter double SAMPLE_DIST = 1.2;
    parameter double DETECTOR_DIST = 4.0;
    parameter double GUI_h = 0.105;
    parameter double GUI_w = 0.1;
    parameter double GUI_GAP = 0.05;
    parameter double H1 = 0.167;
    parameter double W1 = 0.116;
    parameter double H2 = 0.185;
    parameter double W2 = 0.15;
    parameter double H3 = 0.19;
    parameter double W3 = 0.15;
    parameter double H4 = 0.213;
    parameter double W4 = 0.14;
    parameter double H_chop = 0.075;
    parameter double W_chop = 0.03;
    parameter double H_end = 0.042;
    parameter double W_end = 0.0215;
    parameter double ALPHA = 3.4;
    parameter double M = 3.5;
    parameter double F_slow1 = 16.6667;
    parameter double F_slow2 = 0.0;
    parameter double F_fast1 = 0.0;
    parameter double F_fast2 = 200.0;
    parameter int N_fast = 1;
    parameter double SLOW1_THETA = 120.0;
    parameter double FO3 = 1.0;
    parameter double THETA_fast1 = 180.0;
    parameter double FAST_THETA = 5.0;
    parameter double Gamma = 0.0;
    parameter double Etun = 1.0;
    parameter double V_HOLE = 0.0;
    parameter double FRAC_QUASIEL = 0.0;
    parameter double FRAC_TUNNEL = 0.0;
    parameter double TT = 50.0;
    parameter double RES_DE = 0.5;
    parameter double cold = 0.95;

    // Constants
    const double K2V = 3956.0; // Neutron velocity in m/s for given wavelength in Å
    const double VS2E = 81.81; // Neutron energy in meV for given velocity in m/s
    const double ESS_SOURCE_FREQUENCY = 14.0; // ESS source frequency in Hz

    // Derived quantities
    double FREQ = ESS_SOURCE_FREQUENCY;
    double t_offset = Pulse_width / 2.0 + 170e-6;
    double t_FO1 = FO1_DIST * lambda0 / (2 * M_PI * K2V) + t_offset;
    double t_FO2 = Length / 2 * lambda0 / (2 * M_PI * K2V) + t_offset;
    double t_fast1 = (Length / 2 + 0.1) * lambda0 / (2 * M_PI * K2V) + t_offset;
    double t_fast2 = Length * lambda0 / (2 * M_PI * K2V) + t_offset;
    double t_fast2a = (Length + GUI_GAP) * lambda0 / (2 * M_PI * K2V) + t_offset;
    double t_fast3 = (Length + 2 * GUI_GAP) * lambda0 / (2 * M_PI * K2V) + t_offset;
    double t_sample = (Length + SAMPLE_DIST) * lambda0 / (2 * M_PI * K2V) + t_offset;
    double t_detector = (Length + SAMPLE_DIST + DETECTOR_DIST) * lambda0 / (2 * M_PI * K2V) + t_offset;
    double tmin_zoom = t_fast2 * 1e6 - 1e3;
    double tmax_zoom = t_fast2 * 1e6 + 1e3;
    double E_target = VS2E * (K2V * 2 * M_PI / lambda0) * (K2V * 2 * M_PI / lambda0);

    // Source
    ESS_butterfly source(
        sector="W",
        beamline=5,
        cold_frac=cold,
        target_index=6,
        dist=GUI_start,
        focus_xw=GUI_w,
        focus_yh=GUI_h,
        Lmin=Lmin,
        Lmax=Lmax,
        n_pulses=Num_pulses
    ) at(0, 0, -0.1) rotated(0, 0, 0);

    // Progress bar
    Progress_bar Origin at(0, 0, 0) rotated(0, 0, 0);

    // TOF monitor after source
    TOF_monitor TOFmoderator_zoom(
        nt=1000,
        filename="TOFmoderator_zoom.dat",
        xwidth=0.12,
        yheight=0.12,
        tmin=0,
        tmax=5000,
        restore_neutron=1
    ) at(0, 0, 1e-6) relative(Origin) rotated(0, 0, 0);

    // TOF monitor after source
    TOF_monitor TOFmoderator(
        nt=1000,
        filename="TOFmoderator.dat",
        xwidth=0.12,
        yheight=0.12,
        tmin=0,
        tmax=3.0e5,
        restore_neutron=1
    ) at(0, 0, 1e-6) relative(Origin) rotated(0, 0, 0);

    // L monitor at GUI start
    L_monitor Lmon_guistart(
        nL=1000,
        filename="Lmon_guistart.dat",
        xwidth=GUI_w + 0.01,
        yheight=GUI_h + 0.01,
        Lmin=0,
        Lmax=Lmax + 1
    ) at(0, 0, GUI_start - 2e-6) relative(Origin) rotated(0, 0, 0);

    // L monitor for normalization
    L_monitor Lmon_normalize(
        nL=2880,
        filename="Lmon_guistart_normalize.dat",
        xwidth=0.10,
        yheight=0.10,
        Lmin=0,
        Lmax=20
    ) at(0, 0, GUI_start - 1e-6) relative(Origin) rotated(0, 0, 0);

    // Guide after source
    Guide Guide1(
        w1=GUI_w,
        h1=GUI_h,
        w2=W1,
        h2=H1,
        l=FO1_DIST - GUI_start - GUI_GAP / 2,
        R0=1,
        alpha=ALPHA,
        m=M,
        W=0.003
    ) at(0, 0, GUI_start) relative(Origin) rotated(0, 0, 0);

    // L monitor after first guide
    L_monitor Lmonslow1(
        nL=200,
        filename="Lmonslow1.dat",
        xwidth=0.06,
        yheight=0.21,
        Lmin=0,
        Lmax=Lmax + 1
    ) at(0, 0, FO1_DIST - 2e-6) relative(Origin) rotated(0, 0, 0);

    // PSD monitor after first guide
    PSD_monitor PSDslow1(
        filename="PSDslow1.dat",
        xwidth=0.1,
        yheight=0.25
    ) at(0, 0, FO1_DIST - 1e-6) relative(Origin) rotated(0, 0, 0);

    // Disk chopper 1
    DiskChopper FOchop1(
        theta_0=SLOW1_THETA,
        radius=0.6,
        yheight=0.20,
        nu=F_slow1,
        nslit=N_fast,
        delay=t_FO1
    ) at(0, 0, FO1_DIST) relative(Origin) rotated(0, 0, 0);

    // TOF-Lambda monitor after first chopper
    TOFLambda_monitor TOFLmon1(
        nL=200,
        nt=200,
        tmin=0,
        tmax=3e5,
        filename="TOFLmon1.dat",
        xwidth=0.05,
        yheight=0.21,
        Lmin=0,
        Lmax=Lmax + 1
    ) at(0, 0, 1e-6) relative(FOchop1) rotated(0, 0, 0);

    // L monitor after first chopper
    L_monitor Lmon_afterslow1(
        nL=200,
        filename="Lmon_afterslow1.dat",
        xwidth=0.06,
        yheight=0.21,
        Lmin=0,
        Lmax=Lmax + 1
    ) at(0, 0, 2e-6) relative(FOchop1) rotated(0, 0, 0);

    // PSD monitor after first chopper
    PSD_monitor PSD_afterslow1(
        filename="PSD_afterslow1.dat",
        xwidth=0.1,
        yheight=0.25
    ) at(0, 0, 3e-6) relative(FOchop1) rotated(0, 0, 0);

    // Long guide 1
    Guide Guidelong1(
        w1=W1,
        h1=H1,
        w2=W2,
        h2=H2,
        l=L_ballistic_begin + GUI_start - FO1_DIST - GUI_GAP / 2,
        R0=1,
        alpha=ALPHA,
        m=M,
        W=0.003
    ) at(0, 0, GUI_GAP / 2) relative(FOchop1) rotated(0, 0, 0);

    // Long guide 1b
    Guide Guidelong1b(
        w1=W2,
        h1=H2,
        w2=W3,
        h2=H3,
        l=Length / 2 - L_ballistic_begin - GUI_start - GUI_GAP / 2,
        R0=1,
        alpha=ALPHA,
        m=M,
        W=0.003
    ) at(0, 0, L_ballistic_begin + GUI_start) relative(Origin) rotated(0, 0, 0);

    // L monitor after second guide
    L_monitor Lmon_slow2(
        nL=200,
        filename="Lmon_slow2.dat",
        xwidth=0.06,
        yheight=0.21,
        Lmin=0,
        Lmax=Lmax + 1
    ) at(0, 0, Length / 2 - 1e-6) relative(Origin) rotated(0, 0, 0);

    // Disk chopper 2
    DiskChopper FOchop2(
        theta_0=155,
        radius=0.6,
        yheight=0.6,
        nu=F_slow2,
        nslit=N_fast,
        delay=t_FO2
    ) at(0, 0.1, Length / 2) relative(Origin) rotated(0, 0, 0);

    // Fast chopper 1
    DiskChopper Fastchop1(
        theta_0=THETA_fast1,
        radius=0.5,
        yheight=0.5,
        nu=F_fast1,
        nslit=N_fast,
        delay=t_fast1
    ) at(0, 0.1, Length / 2 + GUI_GAP) relative(Origin) rotated(0, 0, 0);

    // PSD monitor after second chopper
    PSD_monitor PSD_afterslow2(
        filename="PSD_afterslow2.dat",
        xwidth=0.1,
        yheight=0.25
    ) at(0, -0.1, 1e-6) relative(Fastchop1) rotated(0, 0, 0);

    // L monitor after second chopper
    L_monitor Lmon_afterslow2(
        nL=200,
        filename="Lmon_afterslow2.dat",
        xwidth=0.06,
        yheight=0.21,
        Lmin=0,
        Lmax=Lmax + 1
    ) at(0, 0, 1e-6) relative(PSD_afterslow2) rotated(0, 0, 0);

    // TOF-Lambda monitor after second chopper
    TOFLambda_monitor TOFL_afterslow2(
        nL=200,
        nt=200,
        tmin=0,
        tmax=3.0e5,
        filename="TOFL_afterslow2.dat",
        xwidth=0.05,
        yheight=0.12,
        Lmin=0,
        Lmax=Lmax + 1
    ) at(0, 0, 1e-6) relative(Lmon_afterslow2) rotated(0, 0, 0);

    // TOF-Lambda monitor after second chopper (zoomed)
    TOFLambda_monitor TOFLfast2zoom(
        nL=200,
        nt=200,
        tmin=tmin_zoom,
        tmax=tmax_zoom,
        filename="TOFLfast2_zoom.dat",
        xwidth=0.05,
        yheight=0.12,
        Lmin=lambda0 - 0.2,
        Lmax=lambda0 + 0.2
    ) at(0, 0, 1e-6) relative(TOFL_afterslow2) rotated(0, 0, 0);

    // PSD monitor after second chopper
    PSD_monitor PSDfast2(
        filename="PSDfast2.dat",
        xwidth=0.1,
        yheight=0.25
    ) at(0, 0, 1e-6) relative(TOFLfast2zoom) rotated(0, 0, 0);

    // Fast chopper 2
    DiskChopper Fastchop2(
        theta_0=FAST_THETA,
        radius=0.35,
        yheight=0.35,
        nu=F_fast2,
        nslit=N_fast,
        delay=t_fast2
    ) at(0, 0.04, Length) relative(Origin) rotated(0, 0, 0);

    // Fast chopper 2 counter
    DiskChopper Fastchop2counter(
        theta_0=FAST_THETA,
        radius=0.35,
        yheight=0.35,
        nu=-F_fast2,
        nslit=N_fast,
        delay=-t_fast2a
    ) at(0, 0.04, Length + GUI_GAP) relative(Origin) rotated(0, 0, 0);

    // Disk chopper 3
    DiskChopper FOchop3(
        theta_0=2 * FAST_THETA,
        radius=0.35,
        yheight=0.35,
        nu=F_fast2 / FO3,
        nslit=N_fast,
        delay=t_fast3
    ) at(0, 0.04, Length + 2 * GUI_GAP) relative(Origin) rotated(0, 0, 0);

    // TOF monitor after third chopper
    TOF_monitor TOFfast2_zoom(
        nt=100,
        filename="TOF_fast2.dat",
        xwidth=1.1,
        yheight=1.2,
        tmin=1e6 * t_fast3 - 2e2,
        tmax=1e6 * t_fast3 + 2e2
    ) at(0, -0.04, 1e-6) relative(FOchop3) rotated(0, 0, 0);

    // L monitor after third chopper
    L_monitor Lmon_afterfast2(
        nL=500,
        filename="Lmon_afterfast2.dat",
        xwidth=0.06,
        yheight=0.18,
        Lmin=0,
        Lmax=Lmax + 1
    ) at(0, 0, 1e-6) relative(TOFfast2_zoom) rotated(0, 0, 0);

    // TOF-Lambda monitor after third chopper
    TOFLambda_monitor TOFL_afterfast2(
        nL=200,
        nt=200,
        tmin=0,
        tmax=3.0e5,
        filename="TOF_afterfast2.dat",
        xwidth=0.05,
        yheight=0.12,
        Lmin=0,
        Lmax=Lmax + 1
    ) at(0, 0, 1e-6) relative(Lmon_afterfast2) rotated(0, 0, 0);

    // TOF-Lambda monitor after third chopper (zoomed)
    TOFLambda_monitor TOFL_afterfast2_zoom(
        nL=200,
        nt=200,
        tmin=tmin_zoom,
        tmax=tmax_zoom,
        filename="TOFL_afterfast2_zoom.dat",
        xwidth=0.05,
        yheight=0.12,
        Lmin=lambda0 - 0.2,
        Lmax=lambda0 + 0.2
    ) at(0, 0, 1e-6) relative(TOFL_afterfast2) rotated(0, 0, 0);

    // PSD monitor after third chopper
    PSD_monitor PSD_afterfast2(
        filename="PSD_afterfast2.dat",
        xwidth=0.1,
        yheight=0.25
    ) at(0, 0, 1e-6) relative(TOFL_afterfast2_zoom) rotated(0, 0, 0);

    // Guide before sample
    Guide Guidesample(
        w1=W_chop,
        h1=H_chop,
        w2=W_end,
        h2=H_end,
        l=SAMPLE_DIST - 4 * GUI_GAP,
        R0=1,
        alpha=ALPHA,
        m=M,
        W=0.003
    ) at(0, 0, GUI_GAP / 2) relative(PSD_afterfast2) rotated(0, 0, 0);

    // L monitor at end of guide before sample
    L_monitor Lmon_guideend(
        nL=1000,
        filename="Lmon_guideend.dat",
        xwidth=W_end + 0.01,
        yheight=H_end + 0.01,
        Lmin=0,
        Lmax=Lmax + 1
    ) at(0, 0, SAMPLE_DIST - 4 * GUI_GAP + 1e-6) relative(Guidesample) rotated(0, 0, 0);

    // PSD monitor before sample
    PSD_monitor PSDsample(
        filename="PSDsample.dat",
        xwidth=0.1,
        yheight=0.25
    ) at(0, 0, SAMPLE_DIST - 3 * GUI_GAP + 1e-6) relative(Lmon_guideend) rotated(0, 0, 0);

    // TOF monitor before sample
    TOF_monitor TOFsample_zoom(
        nt=500,
        filename="TOF_sample.dat",
        xwidth=0.02,
        yheight=0.04,
        tmin=1e6 * t_sample - 5e4,
        tmax=1e6 * t_sample + 5e4
    ) at(0, 0, 1e-6) relative(PSDsample) rotated(0, 0, 0);

    // E monitor before sample
    E_monitor Esample(
        nE=400,
        filename="Esample",
        xwidth=0.02,
        yheight=0.04,
        Emin=E_target - RES_DE,
        Emax=E_target + RES_DE
    ) at(0, 0, 1e-6) relative(TOFsample_zoom) rotated(0, 0, 0);

    // L monitor before sample
    L_monitor Lmon_sample_zoom(
        nL=100,
        filename="LMON_sample_zoom.dat",
        xwidth=0.02,
        yheight=0.04,
        Lmin=lambda0 - 0.1,
        Lmax=lambda0 + 0.1
    ) at(0, 0, 1e-6) relative(Esample) rotated(0, 0, 0);

    // Sample
    Tunneling_sample sample(
        thickness=0.01 - V_HOLE,
        radius=0.01,
        p_interact=1,
        f_QE=FRAC_QUASIEL,
        f_tun=FRAC_TUNNEL,
        gamma=Gamma,
        E_tun=Etun,
        focus_xw=0.015,
        focus_yh=0.015,
        yheight=0.04,
        target_index=2
    ) at(0, -0.04, SAMPLE_DIST) relative(Fastchop2) rotated(0, 0, 0);

    // Detector arm
    Arm detectorarm at(0, 0, 0) relative(sample) rotated(0, TT, 0);

    // TOF monitor at detector
    TOF_monitor TOFdetector(
        nt=512,
        filename="TOF.dat",
        xwidth=0.015,
        yheight=0.015,
        tmin=0,
        tmax=2e5
    ) at(0, 0, DETECTOR_DIST) relative(detectorarm) rotated(0, 0, 0);

    // TOF monitor at detector (zoomed)
    TOF_monitor TOFdetector_zoom(
        nt=100,
        filename="TOF_zoom.dat",
        xwidth=0.015,
        yheight=0.015,
        tmin=1e6 * t_detector - 10e2,
        tmax=1e6 * t_detector + 10e2
    ) at(0, 0, 1e-6) relative(TOFdetector) rotated(0, 0, 0);

    // E monitor at detector
    E_monitor Edetector(
        nE=400,
        filename="Edet",
        xwidth=0.015,
        yheight=0.015,
        Emin=E_target - RES_DE,
        Emax=E_target + RES_DE
    ) at(0, 0, 1e-6) relative(TOFdetector_zoom) rotated(0, 0, 0);

    // TOF2E monitor at detector
    TOF2E_monitor TOF2Edetector(
        nE=200,
        filename="TOF2E.dat",
        xwidth=0.015,
        yheight=0.015,
        Emin=E_target - RES_DE,
        Emax=E_target + RES_DE,
        T_zero=t_sample,
        L_flight=DETECTOR_DIST
    ) at(0, 0, 1e-6) relative(Edetector) rotated(0, 0, 0);

    // Define the beam path
    source
        -> Origin
        -> TOFmoderator_zoom
        -> TOFmoderator
        -> Lmon_guistart
        -> Lmon_normalize
        -> Guide1
        -> Lmonslow1
        -> PSDslow1
        -> FOchop1
        -> TOFLmon1
        -> Lmon_afterslow1
        -> PSD_afterslow1
        -> Guidelong1
        -> Guidelong1b
        -> Lmon_slow2
        -> FOchop2
        -> Fastchop1
        -> PSD_afterslow2
        -> Lmon_afterslow2
        -> TOFL_afterslow2
        -> TOFLfast2zoom
        -> PSDfast2
        -> Fastchop2
        -> Fastchop2counter
        -> FOchop3
        -> TOFfast2_zoom
        -> Lmon_afterfast2
        -> TOFL_afterfast2
        -> TOFL_afterfast2_zoom
        -> PSD_afterfast2
        -> Guidesample
        -> Lmon_guideend
        -> PSDsample
        -> TOFsample_zoom
        -> Esample
        -> Lmon_sample_zoom
        -> sample
        -> detectorarm
        -> TOFdetector
        -> TOFdetector_zoom
        -> Edetector
        -> TOF2Edetector;

    // Set simulation parameters
    set_seed(123456);
    set_ncount(1e6);
}
