    ) at(0, 0, GUI_start - 2e-6) relative(Origin) rotated(0, 0, 0);

    // L monitor for normalization
    L_monitor Lmon_normalize(
        nL=2880,
        filename="Lmon_guistart_normalize.dat",
        xwidth=0.10,
        yheight=0.10,
        Lmin=0,
        Lmax=20
    ) at(0, 0, GUI_start - 1e-6) relative(Origin) rotated(0, 0, 0);

    // Guide after source
    Guide Guide1(
        w1=GUI_w,
        h1=GUI_h,
        w2=W1,
        h2=H1,
        l=FO1_DIST - GUI_start - GUI_GAP / 2,
        R0=1,
        alpha=ALPHA,
        m=M,
        W=0.003
    ) at(0, 0, GUI_start) relative(Origin) rotated(0, 0, 0);

    // L monitor after first guide
    L_monitor Lmonslow1(
        nL=200,
        filename="Lmonslow1.dat",
        xwidth=0.06,
        yheight=0.21,
        Lmin=0,
        Lmax=Lmax + 1
    ) at(0, 0, FO1_DIST - 2e-6) relative(Origin) rotated(0, 0, 0);

    // PSD monitor after first guide
    PSD_monitor PSDslow1(
        filename="PSDslow1.dat",
        xwidth=0.1,
        yheight=0.25
    ) at(0, 0, FO1_DIST - 1e-6) relative(Origin) rotated(0, 0, 0);

    // Disk chopper 1
    DiskChopper FOchop1(
        theta_0=SLOW1_THETA,
        radius=0.6,
        yheight=0.20,
        nu=F_slow1,
        nslit=N_fast,
        delay=t_FO1
    ) at(0, 0, FO1_DIST) relative(Origin) rotated(0, 0, 0);

    // TOF-Lambda monitor after first chopper
    TOFLambda_monitor TOFLmon1(
        nL=200,
        nt=200,
        tmin=0,
        tmax=3e5,
        filename="TOFLmon1.dat",
        xwidth=0.05,
