    ) at(0, 0, GUI_GAP / 2) relative(FOchop1) rotated(0, 0, 0);

    // Long guide 1b
    Guide Guidelong1b(
        w1=W2,
        h1=H2,
        w2=W3,
        h2=H3,
        l=Length / 2 - L_ballistic_begin - GUI_start - GUI_GAP / 2,
