    ) at(0, 0, 1e-6) relative(Lmon_afterslow2) rotated(0, 0, 0);

    // TOF-Lambda monitor after second chopper (zoomed)
    TOFLambda_monitor TOFLfast2zoom(
        nL=200,
        nt=200,
        tmin=tmin_zoom,
        tmax=tmax_zoom,
        filename="TOFLfast2_zoom.dat",
        xwidth=0.05,
        yheight=0.12,
