    ) at(0, 0, 1e-6) relative(TOFLfast2zoom) rotated(0, 0, 0);

    // Fast chopper 2
    DiskChopper Fastchop2(
        theta_0=FAST_THETA,
        radius=0.35,
        yheight=0.35,
        nu=F_fast2,
        nslit=N_fast,
        delay=t_fast2
    ) at(0, 0.04, Length) relative(Origin) rotated(0, 0, 0);

