    ) at(0, 0, SAMPLE_DIST - 4 * GUI_GAP + 1e-6) relative(Guidesample) rotated(0, 0, 0);

    // PSD monitor before sample
    PSD_monitor PSDsample(
        filename="PSDsample.dat",
