    ) at(0, 0, SAMPLE_DIST - 3 * GUI_GAP + 1e-6) relative(Lmon_guideend) rotated(0, 0, 0);

    // TOF monitor before sample
    TOF_monitor TOFsample_zoom(
        nt=500,
